import{_ as i,o as r,c as a,a3 as o,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/import-export-statistik/verwaltung-import-zp10noten.png",f=JSON.parse('{"title":"Noten der Zentralen Prüfung 10 importieren","description":"","frontmatter":{"title":"Noten der Zentralen Prüfung 10 importieren","source_pageid":1116,"source_revision":3971},"headers":[],"relativePath":"schild3/import-export-statistik/zp10-daten-verwaltung-import.md","filePath":"schild3/import-export-statistik/zp10-daten-verwaltung-import.md"}'),s={name:"schild3/import-export-statistik/zp10-daten-verwaltung-import.md"};function d(u,t,p,m,c,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="noten-der-zentralen-prufung-10-importieren" tabindex="-1">Noten der Zentralen Prüfung 10 importieren <a class="header-anchor" href="#noten-der-zentralen-prufung-10-importieren" aria-label="Permalink to &quot;Noten der Zentralen Prüfung 10 importieren&quot;">​</a></h1><p>Bereiten Sie eine Textdatei mit der vorgeschriebenen Kopfzeile und Feldreihenfolge vor. Jede Fachnote wird als eigene Zeile übergeben.</p><p><a href="/bilder/import-export-statistik/verwaltung-import-zp10noten.png"><img src="'+l+`" alt="ZP 10-Noten können über Textdateien über Verwaltung ➜ Import ➜ ZP 10-Daten eingelesen werden." loading="lazy"></a></p><p><em>ZP 10-Noten können über Textdateien über Verwaltung ➜ Import ➜ <strong>ZP 10-Daten</strong> eingelesen werden.</em></p><p>Bei der Import-Datei handelt es sich um eine einfache Textdatei, die auf die Endung &quot;.txt&quot; lauten muss, zum Beispiel <em>ZP10-Noten.txt</em>. Der Dateiname ist jedoch beliebig zu wählen.</p><p>Diese Datei hat das folgende Format, wobei die einzelnen Datenfelder durch ein Semikolon &quot;<strong>;</strong>&quot; getrennt werden.</p><p>Die Datei beginnt mit der Kopfzeile, die auch vorhanden sein muss. In dieser werden in <em>genau dieser Reihenfolge</em> diese Felder codiert:</p><p><em>Nachname, Vorname, Geburtsdatum, Fach, Abschlussnote, Vornote, Note der schriftlichen Prüfung</em> und die Note der <em>mündlichen Prüfung</em>.</p><p>Jede folgende Zeile enthält einen Datensatz zu einem Fach, bei drei Prüfungsfächern erhält also jede Person auch drei Zeilen.</p><p><strong>Dateibeispiel</strong></p><p>Eine Datei könnte beispielhaft also folgende Zeilen enthalten, um die Noten zu übergeben:</p><pre><code>Name;Vorname;Geb-Datum;Fach;Abschlussnote;Vornote;Note schr. Prüfung;Note mündl. Prüfung
Appelius;Simon;05.12.2006;D;3;2;5;3
Appelius;Simon;05.12.2006;E;1;1;1;
Appelius;Simon;05.12.2006;M;3;4;2;
Beckmann;Lisa;26.09.2006;D;1;2;1;1
Beckmann;Lisa;26.09.2006;E;2;2;3;2
Beckmann;Lisa;26.09.2006;M;3;1;5;2
</code></pre>`,12),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,'Die erste Zeile bedeutet, dass "Simon" in Deutsch die Abschlussnote 3 bekommt. Er hatte die Vornote 2, die schriftliche Prüfung 5 und die mündliche Prüfung wurde mit 3 bewertet. Die zweite Zeile steht für Englisch, hier gab es keine mündliche Note und die letzte Stelle bleibt frei.')],-1),e("p",null,"Hierbei ist das korrekte Geburtsdatum wichtig, da SchILD-NRW die Schüler über ihren passenden Namen, Vornamen und das passende Geburtsdatum identifiziert.",-1),e("p",null,[n('Diese Dateien können auch mit Tabellenkalkulationsprogrammen erzeugt werden, hierbei sind die Datenfelder als Textdatei mit einem Semikolon "'),e("strong",null,";"),n('" als Separator zu speichern.')],-1),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,[n("Damit die Noten aus der Datei eingelesen werden können, müssen die Fächer zuvor im Reiter "),e("em",null,"Schüler ➜ ZP 10/ZK"),n(" hinzugefügt worden sein.")]),e("p",null,[n("Mehr hierzu findet sich im Artikel zu diesem Reiter beziehungsweise in dem Artikel zum ZP-10-Gruppenprozess "),e("em",null,"Leistungsdaten holen"),n(".")]),e("p",null,[n("Sind Datei und Fächer vorbereitet, öffnen Sie "),e("strong",null,"Verwaltung → Import → ZP 10-Daten"),n(" und lesen die vorbereitete Textdatei ein.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=ZP10-Daten_(Verwaltung_Import)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 3971.")],-1)])])}const b=i(s,[["render",d]]);export{f as __pageData,b as default};
